@use '../../../../breakpoints' as *;

.event-filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--space-2);
  margin: var(--space-3) var(--margin-mobile);
}

@media (min-width: $breakpoint-tablet) {
  .event-filter-bar {
    margin: var(--space-3) var(--margin-desktop);
    align-items: center;
  }
}

.event-filter-bar__fields {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.event-filter-bar__field {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.event-filter-bar__label {
  font-family: var(--font-body);
  font-size: var(--text-body-sm-size);
  color: var(--color-on-surface-variant);
}

.event-filter-bar__input {
  border: 1px solid var(--color-outline);
  border-radius: var(--radius-sm);
  padding: var(--space-1);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  color: var(--color-on-surface);
  background: var(--color-surface);

  &:focus {
    outline: none;
    border: 2px solid var(--color-primary);
  }
}

.event-filter-bar__chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}

.event-filter-bar__chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  background: var(--color-primary-container);
  color: var(--color-on-primary-container);
  border-radius: var(--radius-full);
  padding-block: var(--space-1);
  padding-inline: var(--space-2);
  font-family: var(--font-body);
  font-size: var(--text-body-sm-size);
}

.event-filter-bar__chip-remove {
  background: none;
  border: none;
  cursor: pointer;
  color: inherit;
  font-size: var(--text-body-size);
  line-height: 1;
  padding: 0;
}

.button-secondary {
  background: transparent;
  color: var(--color-primary);
  border: 1px solid var(--color-outline);
  border-radius: var(--radius-md);
  padding-block: 12px;
  padding-inline: var(--space-3);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  cursor: pointer;
}

