import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto('http://localhost:4200');
await page.waitForSelector('.event-card', { timeout: 10000 });

const cardsBefore = await page.locator('.event-card').count();
console.log('Karten vor Filter:', cardsBefore);

await page.screenshot({ path: '/tmp/01-vor-filter.png', fullPage: true });

// Von-Datum setzen -> nur September-Events ab dem 10.
await page.fill('#von-datum', '2026-09-10');
await page.waitForTimeout(500);

const cardsAfterVon = await page.locator('.event-card').count();
console.log('Karten nach Von-Filter (>=2026-09-10):', cardsAfterVon);
const chipText = await page.locator('.event-filter-bar__chip').first().textContent();
console.log('Chip-Text:', chipText?.trim());

await page.screenshot({ path: '/tmp/02-nach-von-filter.png', fullPage: true });

// Bis-Datum setzen zusaetzlich
await page.fill('#bis-datum', '2026-09-20');
await page.waitForTimeout(500);
const cardsAfterBeide = await page.locator('.event-card').count();
console.log('Karten nach Von+Bis-Filter (09-10 bis 09-20):', cardsAfterBeide);

await page.screenshot({ path: '/tmp/03-nach-beide-filter.png', fullPage: true });

// Reset-Button klicken
const resetButton = page.locator('.button-secondary', { hasText: 'Filter zurücksetzen' });
await resetButton.click();
await page.waitForTimeout(500);
const cardsAfterReset = await page.locator('.event-card').count();
console.log('Karten nach Reset:', cardsAfterReset);
const chipsAfterReset = await page.locator('.event-filter-bar__chip').count();
console.log('Chips nach Reset:', chipsAfterReset);

await browser.close();

